-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Parte 2 de 7. Requiere 01_esquema.sql (columnas profile, skills y
-- mindscapes de characters) y 04_personajes_zzz.sql.
--
-- Datos de los agentes de Zenless Zone Zero sacados de HoYoWiki, la wiki oficial de
-- HoYoverse, con los textos oficiales en espanol:
--   profile     -> sexo, afiliacion, estatura, cumpleanos, actores de voz y version.
--   skills      -> las seis categorias de tecnicas (ataque normal, evasion,
--                  tecnica de apoyo, tecnica especial, tecnica en cadena y
--                  habilidad fundamental) con sus valores por nivel y los
--                  materiales para subirlas.
--   mindscapes  -> los seis niveles de Cine mental.
-- Ademas, los agentes que no tenian biografia reciben el "Diseño de personaje"
-- de la wiki (los que ya tenian una se dejan como estan).
--
-- Sin ficha en la wiki todavia: zzz-roxy.
--
-- Solo actualiza agentes que ya existen; no crea ninguno. Se puede repetir.
--
-- Generado el 2026-09-15.

update public.characters as c
set profile = v.profile,
    skills = v.skills,
    mindscapes = v.mindscapes,
    biography_es = coalesce(c.biography_es, v.biography),
    biography_source_es = case when c.biography_es is null and v.biography is not null then v.source else c.biography_source_es end
from (
  values
  ('zzz-promeia', '[{"campo":"Versión de lanzamiento","valor":"2.8"},{"campo":"Sexo","valor":"Femenino"},{"campo":"Afiliación","valor":"Auditoría Krampus"},{"campo":"Estatura","valor":"174 cm"},{"campo":"Cumpleaños","valor":"23 de diciembre"},{"campo":"Amplificador exclusivo","valor":"Falce escarchada"},{"campo":"Afiliación común","valor":"Dialyn, Banyue, Zhao"},{"campo":"Equipamiento","valor":"Condena del torbellino, Sombra de escarcha, Ejecución del acto final"},{"campo":"Entradas relacionadas","valor":"Cissia, Romeul, Periferia"},{"campo":"VA (CN)","valor":"Yun Hezhui (云鹤追)"},{"campo":"VA (JP)","valor":"Kito Akari (鬼頭明里)"},{"campo":"VA (KO)","valor":"Jeon Haeri (전해리)"},{"campo":"VA (EN)","valor":"Natalie Van Sistine"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/05/06/19629685/f06cb569deef8833140fd2ce305ba2ed_3334206016631839231.png","tecnicas":[{"nombre":"Ataque normal: Filo transversal","descripcion":"Pulsa para usarlo.\nEjecuta hasta cinco movimientos de ataque hacia delante, lo que inflige daño glacial.\nEl quinto movimiento es un ataque en picado. Tras aterrizar y al tener suficiente juicio por frialdad, mantén pulsado o para enlazar la técnica especial EX: Ejecución - Juicio inmisericorde.\nTras lanzar la capa durante el cuarto movimiento, entra en el estado de absolución encadenada."},{"nombre":"Ataque normal: Cuchilla giratoria","descripcion":"Mantén pulsado para usarlo.\nPromeia salta hacia arriba y ejecuta un ataque mientras lanza su capa junto al enemigo para entrar en el estado de absolución encadenada, lo que inflige daño glacial.\nAl golpear al enemigo, no acumula frio corrosivo."},{"nombre":"Absolución encadenada","descripcion":"Al ejecutar ciertas habilidades, Promeia lanza su capa para cortar continuamente a los enemigos, lo que inflige daño glacial.\nAl golpear al enemigo, no acumula frio corrosivo.\nMientras la capa permanece desprendida, Promeia puede caminar lentamente.\nDurante este tiempo, pulsa para enlazar directamente el quinto movimiento del ataque normal: Filo transversal.\nSi Promeia recibe un ataque mientras la capa permanece desprendida, puede ejecutar automáticamente una evasión perfecta. El efecto de evasión puede activarse un máximo de una vez cada 20 s."}],"atributos":[{"clave":"Ataque normal: Filo transversal","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["49.8%","54.4%","59%","63.6%","68.2%","72.8%","77.4%","82%","86.6%","91.2%","95.8%","100.3%","105%","109.6%","114.2%","118.8%"]},{"clave":"Multiplicador de daño de 2.º golpe","valores":["103.2%","112.6%","122%","131.4%","140.8%","150.2%","159.6%","169%","178.4%","187.8%","197.2%","206.6%","216%","225.4%","234.8%","244.2%"]},{"clave":"Multiplicador de daño de 3.er golpe","valores":["190.9%","208.3%","225.7%","243.1%","260.5%","277.9%","295.3%","312.7%","330.1%","347.5%","364.9%","382.3%","399.7%","417.1%","434.5%","451.9%"]},{"clave":"Multiplicador de daño de 4.º golpe","valores":["204.6%","223.4%","242.1%","260.8%","279.5%","298.2%","316.9%","335.6%","354.3%","373%","391.7%","410.4%","429.1%","447.8%","466.5%","485.2%"]},{"clave":"Multiplicador de daño de 5.º golpe","valores":["241.5%","263.5%","285.5%","307.5%","329.5%","351.5%","373.5%","395.5%","417.5%","439.5%","461.5%","483.5%","505.5%","527.5%","549.5%","571.5%"]},{"clave":"Multiplicador de Aturdimiento de 1.er golpe","valores":["33.8%","35.4%","37%","38.6%","40.2%","41.8%","43.4%","45%","46.6%","48.2%","49.8%","51.4%","53%","54.6%","56.2%","57.8%"]},{"clave":"Multiplicador de Aturdimiento de 2.º golpe","valores":["69.1%","72.3%","75.5%","78.7%","81.9%","85.1%","88.3%","91.5%","94.7%","97.9%","101.1%","104.3%","107.5%","110.7%","113.9%","117.1%"]},{"clave":"Multiplicador de Aturdimiento de 3.er golpe","valores":["124.9