/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":18000},{"nombre":"上級感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/33352691c7c57d51fdf1d545033591e1_4673394917071936894.png","cantidad":6}]},{"desde":7,"hasta":8,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":45000},{"nombre":"特化感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":5}]},{"desde":8,"hasta":9,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":67500},{"nombre":"特化感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":8}]},{"desde":9,"hasta":10,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":90000},{"nombre":"特化感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":10}]},{"desde":10,"hasta":11,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":112500},{"nombre":"特化感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":12}]},{"desde":11,"hasta":12,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":135000},{"nombre":"特化感電チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":15},{"nombre":"アクセサリ「ハムスターケージ」","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/09/02/605040b0959e22d31a72e6ef74f064d6_1535631515243165006.png","cantidad":1}]}]}'::jsonb, '[{"nivel":1,"nombre":"La viajera y la presa","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/6335146d351f78f0a628618f2a849181_3119698053713316104.png","efecto":"Al entrar en combate, los ptos. de veneno obtenidos aumentan a 6. El porcentaje de Defensa del enemigo que ignora la técnica pasiva aumenta hasta a un 140 % de su valor original, y el daño infligido por todos los personajes del equipo ignora un 5 % de la resistencia eléctrica del objetivo.\nEl daño infligido por corrosión ósea ignora un 10 % de la resistencia eléctrica del objetivo.","cita":"Los olores, las pisadas, la manera en la que se mueven los ojos... Esas son las pistas que me permiten distinguir a los cazadores de las presas. Me esfumo antes de que me cacen. Inclino la cabeza antes de lanzarme a la caza. Así es como me mantengo con vida. ¿Hogar? Eso solo existe en los cuentos. La naturaleza salvaje e infinita es mi cabaña de caza."},{"nivel":2,"nombre":"Hambre y verdades incómodas","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/469f9554aa138a057dacb98ede59a6d3_8037901845155267600.png","efecto":"Al golpear a un enemigo afectado por Aturdimiento con la técnica en cadena: Crimen organizado o la técnica definitiva: Ofidiofobia, obtiene 3 ptos. de veneno adicionales.\nEl daño del ataque normal: Beso de serpiente aumenta en un 35 %.","cita":"Si en un lugar puedo comer hasta saciarme, es un buen lugar. Si alguien me da de comer, es buena gente. Es la regla más sencilla y de fiar del mundo. Además, el arroz con tortilla es una exquisitez sublime, incluso ese último resto en la cuchara."},{"nivel":3,"nombre":"Cadenas y un nido cálido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/28f2d7ccb68295e6b2c99fb99b577db4_8003165392045521961.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2.","cita":"¿Justicia? ¿Orden? Esas cosas tan honorables me dan escalofríos. Yo conozco las reglas de las sombras: la traición, las mentiras y el arrodillarme si eso significa sobrevivir. No me importa que me usen como herramienta siempre que me paguen con una comida caliente y un rincón donde dormir."},{"nivel":4,"nombre":"La determinación de una villana","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/fc5c9f6a7297408a0823e8ff2d31f79e_3427042453878724993.png","efecto":"Al ejecutar la técnica especial EX, la técnica en cadena o la técnica definitiva, obtiene 1 carga de decisión, hasta un máximo de 3 cargas.\nAl ejecutar el ataque normal: Beso de serpiente, consume todas las cargas de decisión. Por cada carga consumida, activa una instancia adicional de corrosión ósea especial que no consume veneno. Esta instancia de corrosión ósea no puede provocar Aturdimiento.","cita":"El collar que me rodea el cuello está frío. Las esposas son pesadas. Me recuerdan los pecados que no he conseguido expiar. Pero, comparado con esas normas invisibles y las miradas heladas, estas ataduras tienen un precio claro que me tranquiliza. Al menos sé cuánto cuestan. Y cuando vuelva a ese pequeño refugio con sofá y aperitivos, hasta el metal frío me parecerá cálido."},{"nivel":5,"nombre":"Pruebas falsas y colmillos","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/ada22c7100cfcd504dc951c773bb06b8_8375432747173267291.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2.","cita":"Recuerdos quemados por una luz cegadora, crímenes escritos en blanco y negro... Esas «marcas» fueron lo único que me definía, pero ahora las cosas son diferentes. He aprendido a leer y a reconocer el olor de una mentira, y cuando ese olor familiar a artimaña vuelva a inundar el ambiente, no entraré en la jaula como una idiota. Esta vez seré yo quien deje «marcas». Con los dientes. Y no me detendré."},{"nivel":6,"nombre":"Hogar y Barrio N.º6","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/cc8354becbb5422d928dcc39ba6df7fa_4143672430113157989.png","efecto":"Cada vez que activa corrosión ósea, obtiene 1 carga de marca de corrosión ósea.\nCuando cualquier miembro del equipo golpea a un enemigo, excepto si es con corrosión ósea, consume 1 carga de marca de corrosión ósea y activa una instancia de corrosión ósea especial. Esta instancia de corrosión ósea no puede provocar Aturdimiento. Se puede consumir como máximo 1 carga de marca de corrosión ósea cada 3 s.","cita":"Cuando hay algo a lo que quiero aferrarme más que al simple hecho de seguir viva, me vuelvo realmente estúpida. Si el destino alguna vez decide que he de perecer, más te vale que ese gran sofá tuyo tan mullido no tenga a nadie más acostado en él. «No te atrevas a olvidarme... o te morderé hasta matarte.»"}]'::jsonb, 'Cissia, especialista en casos del comisariado del Ministerio de Seguridad Pública de Nueva Eridu, está postulándose activamente como nueva compañera de piso en la segunda planta de Random Play.
Más que el peligro que entrañan las operaciones en sí, lo que más teme son las llamadas de su inspector. Su profesionalidad durante las operaciones es mucho más fiable de lo que su apariencia y palabras parecen demostrar, y es capaz de tomar las decisiones correctas basándose únicamente en sus sentidos e instinto.
Aunque se autodescribe como una villana egoísta y caprichosa guiada por su intuición, las decisiones que toma muestran a menudo destellos de humanidad que van más allá del interés propio. Desprecia el orden y la justicia, pero puede convertirse en la daga más afilada para cazar a los criminales más peligrosos.
Sin embargo, aunque recurra a las mentiras para protegerse, los colmillos para contraatacar o esa filosofía salvaje de «buscar el beneficio propio y huir de los peligros», Cissia los ha transformado en un escudo para proteger lo poco que le queda. No importan ni el pasado ni las cadenas que la atan, pues ya ha decidido echar raíces aquí.

El instinto es la piedra angular de la supervivencia de Cissia, pero también se ha convertido en la gravedad que la arrastra hacia las profundidades del vórtice. Confía demasiado en la información que obtiene de los olores, rastros y reflejos musculares, pero nunca ha aprendido a identificar las trampas ocultas en los contratos escritos y los sistemas autoritarios. Antes de su arresto, su último encargo «legal» fue transportar un lote de suministros confidenciales. El cliente había ofrecido una generosa recompensa y una ruta sencilla, lo que lo convertía en un trabajo fácil para Cissia, que conocía cada callejón oscuro de la Periferia. Como de costumbre, gracias a su vigilancia animal, se coló entre varias ventanas de patrullas, pero lo que no sabía es que cada una de sus maniobras evasivas estaba siendo registrada como prueba de su «conducta furtiva» y sus «habilidades antidetección». Cuando tuvo lugar la gran explosión que lo devoró todo, ella ya había percibido una fluctuación de calor anómala y se había refugiado en una tubería abandonada segundos antes, lo que le salvó la vida, pero también consolidó su identidad de única superviviente y presunta pirómana. En los archivos del Ministerio de Seguridad Pública, su intuición y sus capacidades se malinterpretaron como pruebas de un crimen meticulosamente planeado. El interrogatorio al que la sometieron no buscaba descubrir la verdad, sino exponerla a un procedimiento frío: usaron luces intensas para destruir su tolerancia a la luminosidad, recurrieron a una batería interminable de preguntas para que perdiera la noción del tiempo y, finalmente, cuando su estado físico y mental estuvo al borde del colapso, la empujaron hacia una confesión predispuesta. En medio de tantas desgracias, finalmente la suerte le sonrió: el comisario Severian descubrió las inconsistencias en los registros del interrogatorio de Cissia y la contrató personalmente como especialista en casos basándose en su talento excepcional y su naturaleza bondadosa. A partir de entonces, el collar y las esposas pasaron de ser unas simples ataduras a una peligrosa línea divisoria entre ella y ese sistema de orden que ni entiende ni le inspira confianza.

Belle
¡No hay aperitivo que se resista a la vista y al olfato de Cissia! ¿Cómo es posible que pueda oler las patatas fritas a través de la bolsa?

Wise
Desde que Cissia llegó a casa, no han vuelto a perderse ciertas cosas, como esas viejas cintas de video que nunca encontrábamos. Pero hay otras que nunca hemos vuelto a ver, como la tarta de queso que quedaba en la nevera.', 'https://wiki.hoyolab.com/pc/zzz/entry/1039'),
  ('zzz-nangong-yu', '[{"campo":"Versión de lanzamiento","valor":"2.7"},{"campo":"Género","valor":"Femenino"},{"campo":"Afiliación","valor":"Ángeles de la Delusión"},{"campo":"Estatura","valor":"156 cm"},{"campo":"Cumpleaños","valor":"29 de septiembre"},{"campo":"Amplificador exclusivo","valor":"Delusiones de neón"},{"campo":"Afiliación común","valor":"Sunna, Aria"},{"campo":"Equipamiento","valor":"Nangong Yu: Cambio de foco, Nangong Yu: Contrapunto rítmico, Nangong Yu: Baile en solitario"},{"campo":"Entradas relacionadas","valor":"Cecilia, Ari, Zanahoria dorada auspiciosa, Barrio N.°6, Anillo Estelar, Estrellas de Lyra"},{"campo":"VA (CN)","valor":"Du Qingqing (杜晴晴)"},{"campo":"VA (JP)","valor":"Takao Kanon (高尾奏音)"},{"campo":"VA (KO)","valor":"Im Ji-yeon (임지연)"},{"campo":"VA (EN)","valor":"Michelle Marie"},{"campo":"Cantantes (JP / CN)","valor":"Nicamoq (BPM15Q) (にかもきゅ) / Cuì Shǔ Bǐng (脆鼠饼)"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Paso meteórico","descripcion":"Pulsa para usarlo.\nEjecuta hasta tres movimientos de ataque hacia delante, lo que inflige daño etéreo."},{"nombre":"Ataque normal: Impacto explosivo adorable","descripcion":"Mantén pulsado para ejecutar un ataque cargado, lo que inflige daño etéreo.\nSuelta el botón en el momento preciso para activar la acumulación de carga precisa, lo que hace que el Aturdimiento provocado por la habilidad aumente en un 20 %.\nNangong Yu puede ejecutar hasta tres movimientos de ataque. El segundo y el tercero consumen cada uno 50 tiempos fuertes.\nTras ejecutar la técnica en cadena, la técnica definitiva o la técnica especial EX, al tener suficientes tiempos fuertes, mantén pulsado para omitir el primer movimiento del ataque y ejecutar directamente el segundo y el tercero, los cuales activan la acumulación de carga precisa. Cuando Nangong Yu es el personaje activo, la técnica en cadena, la técnica definitiva y la técnica especial EX no interrumpen el conteo del combo del ataque normal: Impacto explosivo adorable. Durante la acumulación de carga del primer movimiento, el nivel de resistencia a interrupción aumenta y el daño recibido disminuye en un 60 %.\nDurante la acumulación de carga del segundo y el tercer movimiento, el personaje es invulnerable.\nDurante el esprint del primer movimiento, puede bloquear el ataque enemigo. Si logra bloquearlo, el ataque se considera un ataque con acumulación de carga precisa.\nDurante la ejecución de todos los ataques, el personaje es invulnerable."}],"atributos":[{"clave":"Ataque normal: Paso meteórico","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["114.9%","125.4%","135.9%","146.4%","156.9%","167.4%","177.9%","188.4%","198.9%","209.4%","219.9%","230.4%","240.9%","251.4%","261.9%","272.4%"]},{"clave":"Multiplicador de daño de 2.º golpe","valores":["136.9%","149.4%","161.9%","174.4%","186.9%","199.4%","211.9%","224.4%","236.9%","249.4%","261.9%","274.4%","286.9%","299.4%","311.9%","324.4%"]},{"clave":"Multiplicador de daño de 3.er golpe","valores":["263.8%","287.8%","311.8%","335.8%","359.8%","383.8%","407.8%","431.8%","455.8%","479.8%","503.8%","527.8%","551.8%","575.8%","599.8%","623.8%"]},{"clave":"Multiplicador de Aturdimiento de 1.er golpe","valores":["82.7%","86.5%","90.3%","94.1%","97.9%","101.6%","105.5%","109.3%","113.1%","116.9%","120.7%","124.5%","128.3%","132.1%","135.9%","139.7%"]},{"clave":"Multiplicador de Aturdimiento de 2.º golpe","valores":["84.1%","88%","91.9%","95.8%","99.7%","103.6%","107.5%","111.4%","115.3%","119.2%","123.1%","127%","130.9%","134.8%","138.7%","142.6%"]},{"clave":"Multiplicador de Aturdimiento de 3.er golpe","valores":["168.9%",